import { useState } from "react";

function MyForm() {
  const [name, setName] = useState(''); // ✅ use useState directly

  return (
    <form>
      <label>
        Name:
        <input 
          type="text" 
          value={name} 
          onChange={(e) => setName(e.target.value)} 
        />
      </label>
    </form>
  );
}

export default MyForm;
